def solve(input_str):
    lines = input_str.split('\n')
    t = int(lines[0])
    result = []
    for i in range(1, t + 1):
        n = int(lines[i * 2 - 1])
        a = list(map(int, lines[i * 2].split()))
        visited = [0] * n
        if a.count(0) == n or a.count(0)!= 0 and a.index(0) == n - 1:
            result.append('YES')
        else:
            i = 0
            while i < n:
                if a[i] == 0:
                    i += 1
                elif a[i] <= i:
                    result.append('NO')
                    break
                elif a[i] < i and not visited[a[i] - 1]:
                    visited[a[i] - 1] = 1
                    j = i - a[i]
                    while j > 0:
                        if a[j] <= j or a[j] < i or a[j] < j:
                            result.append('NO')
                            break
                        visited[a[j] - 1] = 1
                        j -= 1
                    i = i - a[i]
                else:
                    result.append('NO')
                    break
            else:
                result.append('YES')
    return '\n'.join(result)

