from sys import stdin, stdout

def solve():
    n = int(input().strip())
    books = []
    skills = [0, 0, 0]
    for _ in range(n):
        m, s = input().split()
        m, s = int(m), int(s)
        skills[s] |= 1 << _ + 1
        heapq.heappush(books, (m, _ + 1))
    total_time = float('inf')
    for mask in [(1 << 1) - 1, (1 << 2) - 1, (1 << 1) | (1 << 2) - 1]:
        if skills[mask]!= mask:
            continue
        ans = float('inf')
        q = []
        heapq.heappush(q, (0, 0))
        while q:
            time, book = heapq.heappop(q)
            if book in books:
                m, _ = heapq.heappop(books)
                if m >= time + 1:
                    heapq.heappush(q, (m, _))
            if mask == skills[1] & skills[2]:
                ans = min(ans, time + 1)
            elif skills[mask] & 1:
                ans = min(ans, time)
            elif skills[mask] & 2:
                ans = min(ans, time + 1)
        total_time = min(total_time, ans)
    stdout.write('-1\n' if total_time == float('inf') else f'{total_time}\n')

