            print(-1)
            continue

        pq = [(skill_map[0][0], 0), (skill_map[1][1], 1)]
        heapq.heapify(pq)
        total = 0
        skill_acquired = [0, 0]

        while True:
            cost, i = heapq.heappop(pq)
            if skill_acquired[0] + skill_acquired[1] == 2:
                break

            total += cost
            if i == 0:
                skill_acquired[0] = 1
                if skill_map[0][1] < float('inf'):
                    heapq.heappush(pq, (skill_map[0][1], 0))
            else:
                skill_acquired[1] = 1
                if skill_map[1][0] < float('inf'):
                    heapq.heappush(pq, (skill_map[1][0], 1))

