def solve():
    n, k = map(int, input().split())
    ans = 1
    s = [input() for _ in range(n)]
    for i in range(1, 1 << n):
        agree = 0
        disagree = 0
        tie = False
        for j in range(k):
            Y = 0
            N = 0
            for mask in range(1, 1 << n):
                if i & mask:
                    if s[mask][j] == '+':
                        Y += 1
                    else:
                        N += 1
            if Y > N:
                agree += 1
            elif N > Y:
                disagree += 1
            else:
                tie = True
        if tie:
            ans = max(ans, bin(i).count('1'))
        else:
            if agree >= disagree:
                ans = max(ans, bin(i).count('1'))
    print(ans)

