    min_heap = []
    for key in char_dict:
        heappush(min_heap, (key, -char_dict[key]))
    stack = []
    while min_heap:
        val = heappop(min_heap)
        c, cnt = val[0], -val[1]
        for _ in range(cnt - 1):
            heappush(min_heap, (c, cnt - 1))
        stack.append(c)
    if stack and stack[0] in char_dict and char_dict[stack[0]] > 1:
        stack.insert(0, stack.pop())
    print(''.join(stack))

