        i = queue.popleft()
        if a[i] < b[i]:
            a[i], b[i] = b[i], a[i]
        if i:
            if a[i-1] < a[i]:
                queue.append(i-1)
            if b[i-1] < b[i]:
                queue.append(i-1)
    if a[-1] == max(a) and b[-1] == max(b):
        return "Yes"
    return "No"

