from collections import deque

def solve():
    n, a, b = map(int, input().split())

    if n == a + b or a == 0 or b == 0:
        return "Yes"
    elif max(n - a - b, a, b) == 0:
        return "Yes"
    elif n - a > b or a > n - b:
        return "No"

    def check(n, m, p, q):
        if m == 0:
            return True
        while p > 0 and q > 0 and n - p - m + 1 == n - q - m + 1:
            p -= 1
            q -= 1
        return n - p - m + 1 == n - q - m + 1

    queue = deque([(0, n, 0)])
    visited = {(0, n, 0)}
    while queue:
        x, y, z = queue.popleft()
        if x + y + z == n and z > 0 and check(n, a - z, x, y):
            return "Yes"
        if 0 < x < n - a and x + y + z < n and (x + 1, y - 1, z + 1) not in visited:
            queue.append((x + 1, y - 1, z + 1))
            visited.add((x + 1, y - 1, z + 1))
        if 0 < y < n - a and x + y + z < n and (x - 1, y + 1, z + 1) not in visited:
            queue.append((x - 1, y + 1, z + 1))
            visited.add((x - 1, y + 1, z + 1))

    return "No"

