def solve():
    n, m = map(int, input().split())
    rooks = [tuple(map(int, input().split())) for _ in range(m)]

    queue = deque([(x, y) for x, y in rooks])
    visited = {(x, y): True for x, y in rooks}

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    occupied = {}
    for x, y in rooks:
        occupied.setdefault(x, set()).add(y)
        occupied.setdefault(y, set()).add(x)

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= n and (nx, ny) not in visited:
                occupied.setdefault(nx, set()).add(ny)
                occupied.setdefault(ny, set()).add(nx)
                queue.append((nx, ny))
                visited[(nx, ny)] = True

    for x, y in rooks:
        if len(occupied[x]) < n or len(occupied[y]) < n:
            return "YES"
    return "NO"

