        moves = set()
        for x, y in coords:
            if x == 0:
                moves.add((0, y))
            if y == 0:
                moves.add((x, 0))
        q = [0]
        visited = set([0])
        while q:
            curr = q.pop(0)
            for x, y in moves - visited:
                if (x, y)!= (0, 0):
                    new_distance = distance(0, 0, x, y)
                    if curr + new_distance not in visited:
                        q.append(curr + new_distance)
                        visited.add(curr + new_distance)
        print(min(visited))

