def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        if n == 2:
            print(2)
            print(' '.join(map(str, [1, 2])))
        else:
            d = n
            permutation = []
            curr = 1
            while len(permutation) < n:
                if len(permutation) == 0:
                    permutation.append(curr)
                elif permutation[-1] * d < curr:
                    permutation.append(curr)
                else:
                    permutation.append(permutation[-1] * d)
                curr += 1
                d = ceil(n / (n - len(permutation)))
            print(d)
            print(' '.join(map(str, permutation)))

